input.content:
:root {
  --ink: #17142d;
  --ink-soft: #3e395d;
  --muted: #716d87;
  --line: #e8e4f3;
  --paper: #fbf9ff;
  --surface: #ffffff;
  --soft: #f5f1ff;
  --violet: #6b4cff;
  --violet-deep: #4d2ee0;
  --violet-soft: #eee9ff;
  --coral: #ff5c7c;
  --coral-soft: #ffe8ee;
  --teal: #08a995;
  --teal-soft: #ddf7f2;
  --sun: #ffc84a;
  --sun-deep: #a35c00;
  --blue: #3676ff;
  --rose: #d946a8;
  --danger: #c73658;
  --shadow-sm: 0 6px 20px rgba(45, 30, 96, 0.06);
  --shadow-md: 0 18px 48px rgba(45, 30, 96, 0.1);
  --shadow-lg: 0 30px 80px rgba(35, 22, 82, 0.16);
  --font-sans: "Avenir Next", "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-display: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, serif;
  --radius-sm: 14px;
  --radius-md: 22px;
  --radius-lg: 30px;
  --container: 1180px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  color: var(--ink);
  background:
    radial-gradient(circle at 3% 4%, rgba(107, 76, 255, 0.08), transparent 28rem),
    radial-gradient(circle at 98% 18%, rgba(255, 92, 124, 0.07), transparent 30rem),
    var(--paper);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body.modal-open {
  overflow: hidden;
}

h1,
h2,
h3,
h4,
p,
ul,
ol,
dl,
dd {
  margin: 0;
}

ul,
ol {
  padding: 0;
  list-style: none;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
select,
textarea {
  font: inherit;
}

button {
  cursor: pointer;
}

img,
svg {
  display: block;
}

svg.icon {
  width: 18px;
  height: 18px;
  flex: 0 0 auto;
}

[hidden] {
  display: none !important;
}

::selection {
  color: var(--ink);
  background: rgba(255, 200, 74, 0.7);
}

:focus-visible {
  outline: 3px solid rgba(107, 76, 255, 0.42);
  outline-offset: 3px;
}

.container {
  width: min(var(--container), calc(100% - 48px));
  margin-inline: auto;
}

.visually-hidden {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.skip-link {
  position: fixed;
  top: 12px;
  left: 12px;
  z-index: 200;
  padding: 10px 16px;
  color: #fff;
  background: var(--ink);
  border-radius: 10px;
  transform: translateY(-150%);
  transition: transform 180ms ease;
}

.skip-link:focus {
  transform: translateY(0);
}

.topbar {
  position: relative;
  z-index: 60;
  color: #fff;
  background: linear-gradient(100deg, #25185b 0%, #6b4cff 48%, #df4e9e 100%);
  font-size: 0.78rem;
  letter-spacing: 0.015em;
}

.topbar__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-height: 36px;
  padding-block: 7px;
}

.topbar__message,
.topbar__link {
  display: flex;
  align-items: center;
  gap: 8px;
}

.topbar__message {
  font-weight: 600;
}

.topbar__dot {
  width: 7px;
  height: 7px;
  background: var(--sun);
  border-radius: 50%;
  box-shadow: 0 0 0 4px rgba(255, 200, 74, 0.18);
}

.topbar__link {
  font-weight: 700;
  opacity: 0.92;
  transition: opacity 160ms ease;
}

.topbar__link:hover {
  opacity: 1;
}

.topbar__link svg {
  width: 14px;
  height: 14px;
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  border-bottom: 1px solid rgba(232, 228, 243, 0.85);
  background: rgba(251, 249, 255, 0.88);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
}

.nav-wrap {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px;
  min-height: 80px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  flex: 0 0 auto;
}

.brand__mark {
  position: relative;
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  overflow: hidden;
  color: #fff;
  background: linear-gradient(145deg, var(--violet) 10%, var(--coral) 72%, var(--sun) 100%);
  border-radius: 13px;
  box-shadow: 0 8px 20px rgba(107, 76, 255, 0.26);
}

.brand__mark::before,
.brand__mark::after {
  position: absolute;
  content: "";
  background: rgba(255, 255, 255, 0.28);
  border-radius: 50%;
}

.brand__mark::before {
  top: -16px;
  right: -12px;
  width: 34px;
  height: 34px;
}

.brand__mark::after {
  bottom: -20px;
  left: -12px;
  width: 40px;
  height: 40px;
}

.brand__mark span {
  position: relative;
  z-index: 1;
  font-family: var(--font-display);
  font-size: 1.6rem;
  font-weight: 700;
  line-height: 1;
  transform: translateY(-1px);
}

.brand__copy {
  display: flex;
  flex-direction: column;
  line-height: 1.05;
}

.brand__name {
  font-family: var(--font-display);
  font-size: 1.22rem;
  font-weight: 700;
  letter-spacing: -0.025em;
}

.brand__sub {
  margin-top: 3px;
  color: var(--muted);
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.site-nav {
  display: flex;
  align-items: center;
  gap: 4px;
}

.site-nav__links {
  display: flex;
  align-items: center;
  gap: 3px;
}

.site-nav a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 10px 15px;
  color: var(--muted);
  border-radius: 999px;
  font-size: 0.9rem;
  font-weight: 650;
  white-space: nowrap;
  transition: color 160ms ease, background 160ms ease, transform 160ms ease;
}

.site-nav a:hover {
  color: var(--ink);
  background: rgba(107, 76, 255, 0.07);
}

.site-nav a.is-active {
  color: var(--violet-deep);
  background: var(--violet-soft);
}

.site-nav .nav-cta {
  margin-left: 7px;
  padding-inline: 19px;
  color: #fff;
  background: linear-gradient(120deg, var(--violet), #8d62ff 55%, var(--coral));
  box-shadow: 0 8px 22px rgba(107, 76, 255, 0.24);
}

.site-nav .nav-cta:hover,
.site-nav .nav-cta.is-active {
  color: #fff;
  background: linear-gradient(120deg, var(--violet-deep), #7c4dff 55%, #f04e73);
  transform: translateY(-1px);
}

.plan-count {
  display: inline-grid;
  min-width: 20px;
  height: 20px;
  padding-inline: 6px;
  place-items: center;
