  background: #fff;
  border: 1px solid var(--line);
  border-radius: 13px;
  box-shadow: var(--shadow-sm);
}

.nav-toggle svg {
  width: 22px;
  height: 22px;
  margin: auto;
}

.nav-toggle .icon-close {
  display: none;
}

.nav-toggle.is-open .icon-menu {
  display: none;
}

.nav-toggle.is-open .icon-close {
  display: block;
}

main {
  min-height: 60vh;
}

.hero {
  position: relative;
  padding: 72px 0 58px;
  overflow: hidden;
}

.hero__orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(2px);
  pointer-events: none;
}

.hero__orb--one {
  top: 50px;
  right: -160px;
  width: 470px;
  height: 470px;
  background: radial-gradient(circle at 35% 35%, rgba(255, 92, 124, 0.16), rgba(255, 92, 124, 0));
}

.hero__orb--two {
  bottom: -220px;
  left: -110px;
  width: 460px;
  height: 460px;
  background: radial-gradient(circle at 50% 50%, rgba(107, 76, 255, 0.14), rgba(107, 76, 255, 0));
}

.hero__grid {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(380px, 0.95fr);
  gap: 64px;
  align-items: center;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  margin-bottom: 20px;
  color: var(--violet-deep);
  font-size: 0.73rem;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.eyebrow-dot {
  width: 7px;
  height: 7px;
  background: currentColor;
  border-radius: 50%;
  box-shadow: 0 0 0 4px rgba(107, 76, 255, 0.12);
}

.hero h1 {
  max-width: 720px;
  font-family: var(--font-display);
  font-size: clamp(3.25rem, 6.2vw, 5.35rem);
  font-weight: 650;
  line-height: 0.96;
  letter-spacing: -0.055em;
}

.hero h1 .gradient-text {
  color: transparent;
  background: linear-gradient(110deg, var(--violet-deep), var(--violet) 36%, var(--coral) 72%, #ff8c42);
  -webkit-background-clip: text;
  background-clip: text;
}

.hero__lead {
  max-width: 590px;
  margin-top: 25px;
  color: var(--ink-soft);
  font-size: 1.08rem;
  line-height: 1.7;
}

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 30px;
}

.hero__stats {
  display: flex;
  flex-wrap: wrap;
  gap: 38px;
  margin-top: 40px;
  padding-top: 26px;
  border-top: 1px solid var(--line);
}

.hero-stat strong {
  display: block;
  font-family: var(--font-display);
  font-size: 1.85rem;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.03em;
}

.hero-stat span {
  display: block;
  margin-top: 3px;
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 650;
}

.hero__visual {
  position: relative;
  display: grid;
  min-height: 490px;
  place-items: center;
}

.hero__visual::before {
  position: absolute;
  width: 390px;
  height: 390px;
  content: "";
  background:
    radial-gradient(circle at 35% 28%, rgba(255, 255, 255, 0.9), transparent 30%),
    linear-gradient(145deg, #e7ddff, #ffd9e3 48%, #fff0be);
  border-radius: 46% 54% 62% 38% / 48% 42% 58% 52%;
  transform: rotate(-8deg);
}

.hero-card {
  position: relative;
  z-index: 2;
  width: min(410px, 100%);
  padding: 26px;
  background: rgba(255, 255, 255, 0.94);
  border: 1px solid rgba(255, 255, 255, 0.75);
  border-radius: 32px;
  box-shadow: var(--shadow-lg);
  transform: rotate(-1.5deg);
}

.hero-card__top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}

.hero-card__label {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 8px;
  color: var(--coral);
  font-size: 0.66rem;
  font-weight: 850;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.hero-card__label::before {
  width: 6px;
  height: 6px;
  content: "";
  background: currentColor;
  border-radius: 50%;
}

.hero-card h2 {
  font-family: var(--font-display);
  font-size: 1.65rem;
  line-height: 1.05;
  letter-spacing: -0.035em;
}

.hero-avatar {
  display: grid;
  width: 46px;
  height: 46px;
  flex: 0 0 auto;
  place-items: center;
  color: #fff;
  background: linear-gradient(145deg, var(--violet), var(--coral));
  border-radius: 15px;
  font-size: 0.8rem;
  font-weight: 800;
}

.hero-card__progress {
  margin-top: 24px;
  padding: 18px;
  background: var(--soft);
  border-radius: 20px;
}

.hero-card__progress-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 11px;
  font-size: 0.77rem;
  font-weight: 750;
}

.hero-card__progress-head span:last-child {
  color: var(--violet-deep);
}

.mini-meter {
  height: 7px;
  overflow: hidden;
  background: #e5ddfa;
  border-radius: 99px;
}

.mini-meter span {
  display: block;
  width: 67%;
  height: 100%;
  background: linear-gradient(90deg, var(--violet), var(--coral));
  border-radius: inherit;
}

.hero-card__courses {
  display: grid;
  gap: 9px;
  margin-top: 14px;
}

.hero-course {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 16px;
}

.hero-course__swatch {
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  background: linear-gradient(145deg, var(--violet), #a885ff);
  border-radius: 12px;
}

.hero-course__swatch--coral {
  background: linear-gradient(145deg, #ff4f7f, #ff9b7a);
}

.hero-course__swatch--teal {
  background: linear-gradient(145deg, #00a48f, #48ddc1);
}

.hero-course__copy {
  min-width: 0;
  flex: 1;
}

.hero-course__copy strong {
  display: block;
  font-size: 0.82rem;
  line-height: 1.25;
}

.hero-course__copy span {
  display: block;
  margin-top: 2px;
  overflow: hidden;
  color: var(--muted);
  font-size: 0.68rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.hero-course__time {
  color: var(--muted);
  font-size: 0.63rem;
  font-weight: 750;
  white-space: nowrap;
}

.hero-card__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 18px;
  padding-top: 16px;
  border-top: 1px solid var(--line);
  font-size: 0.72rem;
  font-weight: 750;
}

.hero-card__footer span {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
}

.hero-card__footer svg {
  width: 15px;
  height: 15px;
  color: var(--coral);
}

.hero-card__go {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  color: #fff;
  background: var(--ink);
  border-radius: 50%;
}

.hero-card__go svg {
  width: 16px;
  height: 16px;
  color: currentColor;
}

.floating-pill {
  position: absolute;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 11px 14px;
  background: #fff;
  border: 1px solid rgba(232, 228, 243, 0.8);
  border-radius: 14px;
  box-shadow: var(--shadow-md);
  font-size: 0.69rem;
  font-weight: 750;
  animation: float 5s ease-in-out infinite;
}

.floating-pill svg {
  width: 16px;
  height: 16px;
}

.floating-pill--top {
  top: 42px;
  right: 0;
  color: #087e70;
}

.floating-pill--bottom {
  bottom: 39px;
  left: 4px;
  color: var(--violet-deep);
  animation-delay: -2.3s;
}

@keyframes float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-8px);
  }
}

.btn {
  display: inline-flex;
  min-height: 48px;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 12px 20px;
  color: var(--ink);
  background: transparent;
  border: 1px solid transparent;
  border-radius: 14px;
  font-size: 0.87rem;
  font-weight: 750;
  line-height: 1.2;
  text-align: center;
  white-space: nowrap;
  transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease, border-color 160ms ease;
}

.btn svg {
  width: 17px;
  height: 17px;
}

.btn:hover {
  transform: translateY(-1px);
}

.btn--primary {
  color: #fff;
  background: linear-gradient(120deg, var(--violet), #825cff 52%, var(--coral));
  box-shadow: 0 10px 24px rgba(107, 76, 255, 0.24);
}

.btn--primary:hover {
  background: linear-gradient(120deg, var(--violet-deep), #7248f5 52%, #f04b70);
  box-shadow: 0 13px 28px rgba(107, 76, 255, 0.31);
}

.btn--ink {
  color: #fff;
  background: var(--ink);
}

.btn--ink:hover {
  background: #282347;
}

.btn--ghost {
  color: var(--ink-soft);
  background: #fff;
  border-color: var(--line);
}

.btn--ghost:hover {
  background: var(--soft);
  border-color: #d8d0ee;
}

.btn--white {
  color: var(--ink);
  background: #fff;
  box-shadow: 0 10px 30px rgba(24, 13, 70, 0.2);
}

.btn--glass {
  color: #fff;
  background: rgba(255, 255, 255, 0.12);
  border-color: rgba(255, 255, 255, 0.32);
}

.btn--glass:hover {
  background: rgba(255, 255, 255, 0.2);
}

.btn--small {
  min-height: 40px;
  padding: 9px 14px;
  border-radius: 12px;
  font-size: 0.78rem;
}

.btn--tiny {
  min-height: 34px;
  padding: 7px 10px;
  border-radius: 10px;
  font-size: 0.72rem;
}

.btn--danger-ghost {
  color: var(--danger);
  background: #fff5f7;
  border-color: #ffdce4;
}

.btn--danger-ghost:hover {
  background: #ffe9ee;
  border-color: #ffc8d3;
}

.btn:disabled {
  cursor: not-allowed;
  opacity: 0.55;
  transform: none;
  box-shadow: none;
}

.section {
  padding: 72px 0;
}

.section--tight {
  padding: 48px 0 76px;
}

.section--soft {
  position: relative;
  background: linear-gradient(180deg, rgba(245, 241, 255, 0.76), rgba(251, 249, 255, 0));
}

.section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 28px;
  margin-bottom: 30px;
}

.section-heading .eyebrow {
  margin-bottom: 10px;
}

.section-heading h2 {
  font-family: var(--font-display);
  font-size: clamp(2rem, 3.6vw, 2.9rem);
  font-weight: 650;
  line-height: 1.04;
  letter-spacing: -0.045em;
}

.section-heading p {
  max-width: 600px;
  margin-top: 10px;
  color: var(--muted);
  font-size: 0.94rem;
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--violet-deep);
  font-size: 0.84rem;
  font-weight: 800;
  white-space: nowrap;
}

.text-link svg {
  width: 16px;
  height: 16px;
  transition: transform 160ms ease;
}

.text-link:hover svg {
  transform: translateX(3px);
}

.faculty-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
}

.faculty-card {
  position: relative;
  display: grid;
  min-height: 126px;
  grid-template-columns: auto 1fr;
  gap: 14px;
  align-items: start;
  overflow: hidden;
  padding: 20px;
  color: var(--ink);
  border: 1px solid rgba(255, 255, 255, 0.84);
  border-radius: 24px;
  box-shadow: 0 10px 28px rgba(45, 30, 96, 0.04);
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.faculty-card::after {
  position: absolute;
  right: -30px;
  bottom: -50px;
  width: 110px;
  height: 110px;
  content: "";
  background: rgba(255, 255, 255, 0.26);
  border-radius: 50%;
}

.faculty-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.faculty-card--1 {
  background: linear-gradient(135deg, #ece6ff, #dcd0ff);
}

.faculty-card--2 {
  background: linear-gradient(135deg, #ffe6ed, #ffd0dc);
}

.faculty-card--3 {
  background: linear-gradient(135deg, #dcf9f2, #bff1e8);
}

.faculty-card--4 {
  background: linear-gradient(135deg, #e5edff, #cfddff);
}

.faculty-card--5 {
  background: linear-gradient(135deg, #ffe9fa, #ffd3f1);
}

.faculty-card--6 {
  background: linear-gradient(135deg, #fff2cf, #ffe6a7);
}

.faculty-card__icon {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  color: var(--ink);
  background: rgba(255, 255, 255, 0.55);
  border-radius: 15px;
}

.faculty-card__icon svg {
  width: 23px;
  height: 23px;
}

.faculty-card__copy {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 3px;
  padding-top: 2px;
}

.faculty-card__copy strong {
  font-size: 0.96rem;
  line-height: 1.2;
}

.faculty-card__copy span {
  color: var(--ink-soft);
  font-size: 0.75rem;
}

.faculty-card__count {
  grid-column: 2;
  align-self: end;
  color: var(--ink-soft);
  font-size: 0.7rem;
  font-weight: 750;
}

.faculty-card__arrow {
  position: absolute;
  top: 18px;
  right: 18px;
  z-index: 1;
  display: grid;
  width: 29px;
  height: 29px;
  place-items: center;
  color: var(--ink);
  background: rgba(255, 255, 255, 0.6);
  border-radius: 50%;
  transition: transform 180ms ease;
}

.faculty-card__arrow svg {
  width: 14px;
  height: 14px;
}

.faculty-card:hover .faculty-card__arrow {
  transform: translateX(2px);
}

.course-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
}

.course-card {
  display: flex;
  min-width: 0;
  flex-direction: column;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 27px;
  box-shadow: 0 9px 26px rgba(45, 30, 96, 0.05);
  transition: transform 180ms ease, box-shadow 180ms ease;
}

.course-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-md);
}

.theme-1 {
  --theme: #5d3bff;
  --theme-soft: #eee9ff;
  --course-gradient: linear-gradient(135deg, #5b38f2 0%, #9b75ff 100%);
}

.theme-2 {
  --theme: #e83f68;
  --theme-soft: #ffe9ef;
  --course-gradient: linear-gradient(135deg, #ed426c 0%, #ff9a78 100%);
}

.theme-3 {
  --theme: #058779;
  --theme-soft: #ddf7f1;
  --course-gradient: linear-gradient(135deg, #008d80 0%, #3dd9bd 100%);
}

.theme-4 {
  --theme: #b75b00;
  --theme-soft: #fff3d6;
  --course-gradient: linear-gradient(135deg, #c76c00 0%, #ffc544 100%);
}

.theme-5 {
  --theme: #2454cf;
  --theme-soft: #e7efff;
  --course-gradient: linear-gradient(135deg, #2454cf 0%, #6ea4ff 100%);
}

.theme-6 {
  --theme: #a52786;
  --theme-soft: #ffe7f7;
  --course-gradient: linear-gradient(135deg, #ac2690 0%, #f06fbe 100%);
}

.course-card__art {
  position: relative;
  min-height: 156px;
  overflow: hidden;
  padding: 21px;
  color: #fff;
  background: var(--course-gradient);
}

.course-card__art::before,
.course-card__art::after {
  position: absolute;
  content: "";
  background: rgba(255, 255, 255, 0.11);
  border-radius: 50%;
}

.course-card__art::before {
  top: -70px;
  right: -34px;
  width: 160px;
  height: 160px;
}

.course-card__art::after {
  right: 70px;
  bottom: -80px;
  width: 130px;
  height: 130px;
}

.course-card__monogram {
  position: absolute;
  right: 5px;
  bottom: -37px;
  z-index: 0;
  color: #fff;
  font-family: var(--font-display);
  font-size: 8.6rem;
  font-weight: 700;
  line-height: 1;
  opacity: 0.13;
  letter-spacing: -0.08em;
  pointer-events: none;
}

.course-card__topline {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.dept-pill,
.rating-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 25px;
  padding: 4px 9px;
  background: rgba(255, 255, 255, 0.16);
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 999px;
  font-size: 0.62rem;
  font-weight: 800;
  letter-spacing: 0.045em;
  line-height: 1;
  backdrop-filter: blur(5px);
}

.dept-pill {
  max-width: 70%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-transform: uppercase;
}

.rating-chip svg {
  width: 12px;
  height: 12px;
  color: var(--sun);
}

.course-card__code {
  position: relative;
  z-index: 1;
  margin-top: 29px;
  font-size: 1.37rem;
  font-weight: 850;
  letter-spacing: 0.045em;
  line-height: 1;
}

.course-card__format {
  position: relative;
  z-index: 1;
  margin-top: 7px;
  font-size: 0.67rem;
  font-weight: 650;
  opacity: 0.8;
