.course-card__body {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 14px;
  padding: 21px;
}

.course-card__heading h3 {
  font-size: 1.27rem;
  font-weight: 780;
  line-height: 1.16;
  letter-spacing: -0.025em;
