.profile-avatar {
  display: grid;
  width: 92px;
  height: 92px;
  flex: 0 0 auto;
  place-items: center;
  color: #fff;
  background: linear-gradient(140deg, rgba(255, 255, 255, 0.28), rgba(255, 255, 255, 0.1));
  border: 2px solid rgba(255, 255, 255, 0.35);
  border-radius: 27px;
  box-shadow: inset 0 0 22px rgba(255, 255, 255, 0.1);
  font-family: var(--font-display);
  font-size: 2.2rem;
  font-weight: 700;
  letter-spacing: -0.03em;
  backdrop-filter: blur(10px);
}

.profile-banner .eyebrow {
  margin-bottom: 6px;
  color: #ffe49a;
}

.profile-banner h1 {
  font-family: var(--font-display);
  font-size: clamp(2.1rem, 4.3vw, 3.4rem);
  font-weight: 650;
  line-height: 1;
  letter-spacing: -0.045em;
}

.profile-banner__program {
  margin-top: 8px;
  color: rgba(255, 255, 255, 0.78);
  font-size: 0.88rem;
}

.profile-banner__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 14px;
}

.profile-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 9px;
  color: rgba(255, 255, 255, 0.9);
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.16);
  border-radius: 999px;
  font-size: 0.65rem;
  font-weight: 700;
}

.profile-chip svg {
  width: 12px;
  height: 12px;
}

.profile-banner__actions {
  position: relative;
  z-index: 1;
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
}

.profile-banner__actions .btn--glass {
  color: #fff;
}

.profile-banner__actions .btn--white {
  color: var(--ink);
}

.profile-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(280px, 0.7fr);
  gap: 24px;
  margin-top: 24px;
}

.profile-details {
  display: grid;
  gap: 22px;
}

.profile-details h2,
.progress-card h2 {
  font-family: var(--font-display);
  font-size: 1.6rem;
  font-weight: 650;
  letter-spacing: -0.03em;
}

.details-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 19px 24px;
}

.details-list div {
  min-width: 0;
}

.details-list dt {
  margin-bottom: 3px;
  color: var(--muted);
  font-size: 0.64rem;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.details-list dd {
  overflow: hidden;
  color: var(--ink);
  font-size: 0.87rem;
  font-weight: 700;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.progress-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 24px;
  background: linear-gradient(150deg, #f6f1ff, #fff3f7);
  border-color: #ebe4fb;
}

.progress-card__head p {
  margin-top: 5px;
  color: var(--muted);
  font-size: 0.78rem;
}

.progress-card__body {
  display: flex;
  align-items: center;
  gap: 20px;
}

.progress-ring {
  position: relative;
  display: grid;
  width: 118px;
  height: 118px;
  flex: 0 0 auto;
  place-items: center;
  background: conic-gradient(var(--violet) calc(var(--progress, 0) * 1%), rgba(255, 255, 255, 0.9) 0);
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px rgba(107, 76, 255, 0.06);
}

.progress-ring::after {
  position: absolute;
  inset: 10px;
  content: "";
  background: #fcfaff;
  border-radius: 50%;
}

.progress-ring span {
  position: relative;
  z-index: 1;
  color: var(--violet-deep);
  font-family: var(--font-display);
  font-size: 1.55rem;
  font-weight: 700;
}

.progress-card__copy {
  display: grid;
  gap: 4px;
}

.progress-card__copy strong {
  font-size: 0.84rem;
}

.progress-card__copy span {
  color: var(--muted);
  font-size: 0.72rem;
}

.profile-stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 11px;
}

.profile-stat {
  padding: 13px;
  background: rgba(255, 255, 255, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.8);
  border-radius: 14px;
}

.profile-stat strong {
  display: block;
  font-family: var(--font-display);
  font-size: 1.4rem;
  line-height: 1;
}

.profile-stat span {
  display: block;
  margin-top: 4px;
  color: var(--muted);
  font-size: 0.6rem;
  font-weight: 750;
  white-space: nowrap;
}

.schedule-section {
  margin-top: 30px;
}

.schedule-section .section-heading {
  margin-bottom: 18px;
}

.schedule-section .section-heading h2 {
  font-size: clamp(1.8rem, 3.3vw, 2.5rem);
}

.modal {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: grid;
  padding: 20px;
  place-items: center;
}

.modal__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(20, 15, 47, 0.62);
  opacity: 0;
  backdrop-filter: blur(5px);
  transition: opacity 200ms ease;
}

.modal__panel {
  position: relative;
  width: min(590px, 100%);
  max-height: calc(100vh - 40px);
  overflow-y: auto;
  padding: 32px;
  background: #fff;
  border: 1px solid rgba(255, 255, 255, 0.7);
  border-radius: 30px;
  box-shadow: 0 35px 100px rgba(16, 10, 43, 0.35);
  opacity: 0;
  outline: none;
  transform: translateY(14px) scale(0.985);
  transition: opacity 200ms ease, transform 200ms ease;
}

.modal.is-open .modal__backdrop {
  opacity: 1;
}

.modal.is-open .modal__panel {
  opacity: 1;
  transform: translateY(0) scale(1);
}

.modal__close {
  position: absolute;
  top: 18px;
  right: 18px;
  display: grid;
  width: 36px;
  height: 36px;
  padding: 0;
  place-items: center;
  color: var(--muted);
  background: #f8f6fd;
  border: 1px solid var(--line);
  border-radius: 11px;
  transition: color 140ms ease, background 140ms ease;
}

.modal__close:hover {
  color: var(--ink);
  background: var(--soft);
}

.modal__close svg {
  width: 16px;
  height: 16px;
}

.modal .eyebrow {
  margin-bottom: 11px;
}

.modal h2 {
  padding-right: 36px;
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 2.7rem);
  font-weight: 650;
  line-height: 1.02;
  letter-spacing: -0.045em;
}

.modal-intro {
  margin-top: 9px;
  color: var(--muted);
  font-size: 0.85rem;
}

.review-student {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  margin-top: 21px;
}

.review-student > div {
  display: grid;
  gap: 2px;
  padding: 13px 14px;
  background: #faf8ff;
  border: 1px solid var(--line);
  border-radius: 13px;
}

.review-student span {
  color: var(--muted);
  font-size: 0.6rem;
  font-weight: 850;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.review-student strong {
  font-size: 0.79rem;
}

.review-student small {
  overflow: hidden;
  color: var(--muted);
  font-size: 0.66rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.review-courses {
  display: grid;
  gap: 6px;
  margin-top: 16px;
}

.review-courses li {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 10px;
  border-bottom: 1px solid var(--line);
}

.review-courses li:last-child {
  border-bottom: 0;
}

.review-course-copy {
  display: grid;
  min-width: 0;
  flex: 1;
  gap: 1px;
}

.review-course-copy strong {
  overflow: hidden;
  font-size: 0.77rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.review-course-copy small {
  overflow: hidden;
  color: var(--muted);
  font-size: 0.66rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.review-course-credits {
  color: var(--muted);
  font-size: 0.7rem;
  font-weight: 750;
  white-space: nowrap;
}

.review-total {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 11px;
  padding: 15px 17px;
  background: linear-gradient(120deg, var(--violet-soft), var(--coral-soft));
  border-radius: 14px;
  font-size: 0.79rem;
  font-weight: 750;
}

.review-total strong {
  font-family: var(--font-display);
  font-size: 1.4rem;
  line-height: 1;
}

.modal-note {
  margin-top: 13px;
  color: var(--muted);
  font-size: 0.68rem;
  line-height: 1.5;
}

.modal__actions {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
  margin-top: 24px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
}

.success-view {
  text-align: center;
}

.success-view .eyebrow {
  justify-content: center;
}

.success-mark {
  display: grid;
  width: 72px;
  height: 72px;
  margin: 3px auto 18px;
  place-items: center;
  color: #fff;
  background: linear-gradient(145deg, var(--teal), #51ddc0);
  border-radius: 50%;
  box-shadow: 0 12px 28px rgba(8, 169, 149, 0.26);
  animation: pop 350ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

.success-mark svg {
  width: 34px;
  height: 34px;
}

@keyframes pop {
  from {
    opacity: 0;
    transform: scale(0.65);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.success-view h2 {
  padding: 0;
}

.success-view > p {
  max-width: 420px;
  margin: 9px auto 0;
  color: var(--muted);
  font-size: 0.84rem;
}

.confirmation-code {
  margin: 22px auto 0;
  padding: 17px;
  background: linear-gradient(120deg, var(--soft), #fff5f8);
  border: 1px dashed #d8cff2;
  border-radius: 15px;
}

.confirmation-code span {
  display: block;
  color: var(--muted);
  font-size: 0.61rem;
  font-weight: 850;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.confirmation-code strong {
  display: block;
  margin-top: 4px;
  color: var(--violet-deep);
  font-size: 1.1rem;
  letter-spacing: 0.07em;
}

.success-view .modal-note {
  margin-inline: auto;
  max-width: 390px;
}

.toast-region {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 130;
  display: grid;
  width: min(400px, calc(100vw - 40px));
  gap: 9px;
  pointer-events: none;
}

.toast {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 13px 14px;
  color: #fff;
  background: #1d1838;
  border-left: 4px solid #4ed8bf;
  border-radius: 14px;
  box-shadow: 0 18px 45px rgba(20, 13, 55, 0.25);
  font-size: 0.78rem;
  font-weight: 650;
  pointer-events: auto;
  animation: toast-in 230ms ease both;
}

.toast--warning {
  border-left-color: var(--sun);
}

.toast.is-leaving {
  animation: toast-out 240ms ease both;
}

.toast__icon {
  display: grid;
  width: 25px;
  height: 25px;
  flex: 0 0 auto;
  place-items: center;
  color: #4ed8bf;
  background: rgba(78, 216, 191, 0.13);
  border-radius: 8px;
}

.toast--warning .toast__icon {
  color: var(--sun);
  background: rgba(255, 200, 74, 0.13);
}

.toast__icon svg {
  width: 15px;
  height: 15px;
}

.toast__message {
  flex: 1;
}

.toast__action {
  color: #ffe07c;
  font-size: 0.72rem;
  font-weight: 800;
  white-space: nowrap;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.toast__close {
  display: grid;
  width: 26px;
  height: 26px;
  padding: 0;
  place-items: center;
  color: #a9a3bd;
  background: transparent;
  border: 0;
  border-radius: 7px;
}

.toast__close:hover {
  color: #fff;
  background: rgba(255, 255, 255, 0.08);
}

.toast__close svg {
  width: 13px;
  height: 13px;
}

@keyframes toast-in {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes toast-out {
  to {
    opacity: 0;
    transform: translateY(8px);
  }
}

@media (max-width: 1100px) {
  .hero__grid {
    gap: 34px;
  }

  .hero h1 {
    font-size: clamp(3rem, 6.6vw, 4.5rem);
  }

  .course-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .course-card--featured:last-child {
    display: none;
  }

  .profile-banner {
    padding: 30px;
  }
}

@media (max-width: 980px) {
  .faculty-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .page-hero__inner {
    align-items: flex-start;
    flex-direction: column;
    gap: 24px;
  }

  .registration-layout {
    grid-template-columns: 1fr;
  }

  .summary-card {
    position: static;
  }

  .summary-stats {
    grid-template-columns: 1fr 1fr;
  }

  .profile-grid {
    grid-template-columns: 1fr;
  }

  .profile-banner {
    align-items: flex-start;
    flex-direction: column;
  }

  .cta-band {
    grid-template-columns: 1fr;
    gap: 30px;
    padding: 42px;
  }

  .cta-band__aside {
    max-width: 390px;
  }
}

@media (max-width: 900px) {
  .nav-toggle {
    display: grid;
  }

  .site-nav {
    position: absolute;
    top: calc(100% + 10px);
    right: 0;
    left: 0;
    display: block;
    padding: 10px;
    visibility: hidden;
    background: #fff;
    border: 1px solid var(--line);
    border-radius: 18px;
    box-shadow: var(--shadow-lg);
    opacity: 0;
    transform: translateY(-8px);
    transition: opacity 160ms ease, transform 160ms ease, visibility 160ms ease;
  }

  .site-nav.is-open {
    visibility: visible;
    opacity: 1;
    transform: translateY(0);
  }

  .site-nav__links {
    display: grid;
    gap: 3px;
  }

  .site-nav a,
  .site-nav .nav-cta {
    justify-content: space-between;
    margin: 0;
    padding: 12px 14px;
    border-radius: 12px;
  }

  .site-nav .nav-cta {
    margin-top: 4px;
  }

  .hero {
    padding-top: 50px;
  }

  .hero__grid {
    grid-template-columns: 1fr;
    gap: 42px;
  }

  .hero__copy {
    max-width: 700px;
  }

  .hero__visual {
    min-height: 430px;
  }

  .hero__visual::before {
    width: 350px;
    height: 350px;
  }

  .floating-pill--top {
    right: 8%;
  }

  .floating-pill--bottom {
    left: 8%;
  }

  .field-grid {
    grid-template-columns: 1fr;
  }

  .field--full {
    grid-column: auto;
  }

  .details-list {
    grid-template-columns: 1fr 1fr;
  }

  .profile-stats {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 720px) {
  .container {
    width: min(var(--container), calc(100% - 32px));
  }

  .topbar__inner {
    justify-content: center;
    text-align: center;
  }

  .topbar__link {
    display: none;
  }

  .nav-wrap {
    min-height: 72px;
  }

  .brand__mark {
    width: 38px;
    height: 38px;
    border-radius: 12px;
  }

  .brand__name {
    font-size: 1.1rem;
  }

  .hero {
    padding: 42px 0 46px;
  }

  .hero h1 {
    font-size: clamp(2.85rem, 11.5vw, 4rem);
  }

  .hero__lead {
    font-size: 0.98rem;
  }

  .hero__stats {
    gap: 24px;
  }

  .hero-stat strong {
    font-size: 1.55rem;
  }

  .hero__visual {
    min-height: 400px;
  }

  .hero-card {
    padding: 21px;
    border-radius: 26px;
  }

  .floating-pill {
    font-size: 0.61rem;
  }

  .section {
    padding: 54px 0;
  }

  .section-heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 13px;
  }

  .faculty-grid {
    grid-template-columns: 1fr 1fr;
  }

  .course-grid {
    grid-template-columns: 1fr;
  }

  .course-card--featured:last-child {
    display: flex;
  }

  .cta-band {
    padding: 32px 26px;
    border-radius: 27px;
  }

  .footer-grid {
    grid-template-columns: 1fr 1fr;
  }

  .footer-grid > :first-child {
    grid-column: 1 / -1;
  }

  .footer-bottom {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }

  .page-hero {
    padding-top: 40px;
  }

  .page-hero h1 {
    font-size: clamp(2.55rem, 9.8vw, 3.4rem);
  }

  .catalog-meta {
    align-items: flex-start;
    flex-direction: column;
    gap: 9px;
  }

  .catalog-meta__left {
    align-items: flex-start;
    flex-direction: column;
    gap: 6px;
  }

  .course-picker {
    align-items: stretch;
    flex-direction: column;
  }

  .course-picker .btn {
    width: 100%;
  }

  .panel {
    padding: 22px;
    border-radius: 24px;
  }

  .panel__heading {
    flex-direction: column;
    gap: 10px;
  }

  .profile-banner {
    padding: 25px;
    border-radius: 26px;
  }

  .profile-banner__main {
    align-items: flex-start;
    flex-direction: column;
    gap: 15px;
  }

  .profile-avatar {
    width: 75px;
    height: 75px;
    border-radius: 22px;
    font-size: 1.8rem;
  }

  .profile-banner__actions {
    width: 100%;
  }

  .profile-banner__actions .btn {
    flex: 1;
  }

  .details-list {
    grid-template-columns: 1fr;
    gap: 15px;
  }

  .progress-card__body {
    align-items: flex-start;
    flex-direction: column;
  }

  .modal__panel {
    padding: 26px 22px;
    border-radius: 24px;
  }

  .review-student {
    grid-template-columns: 1fr;
  }

  .modal__actions {
    flex-direction: column-reverse;
  }

  .modal__actions .btn {
    width: 100%;
  }

  .toast-region {
    right: 16px;
    bottom: 16px;
    width: calc(100vw - 32px);
  }
}

@media (max-width: 520px) {
  .container {
    width: min(var(--container), calc(100% - 24px));
  }

  .brand__sub {
    display: none;
  }

  .hero__actions .btn {
    width: 100%;
  }

  .hero__visual {
    min-height: 380px;
  }

  .hero-card h2 {
    font-size: 1.45rem;
  }

  .floating-pill--top {
    top: 12px;
    right: 0;
  }

  .floating-pill--bottom {
    bottom: 12px;
    left: 0;
  }

  .hero-card__time {
    display: none;
  }

  .faculty-grid {
    grid-template-columns: 1fr;
  }

  .faculty-card {
    min-height: 110px;
  }

  .course-card__footer {
    align-items: flex-start;
    flex-direction: column;
  }

  .course-card__footer .btn,
  .course-state {
    width: 100%;
    justify-content: center;
  }

  .cta-band {
    padding: 28px 22px;
  }

  .cta-band__actions .btn {
    width: 100%;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  .profile-stats {
    grid-template-columns: 1fr;
  }

  .profile-banner__actions {
    flex-direction: column;
  }

  .filter-group {
    flex-basis: 100%;
  }

  .summary-stats {
    grid-template-columns: 1fr 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

@media print {
  .topbar,
  .site-header,
  .site-footer,
  .profile-banner__actions,
  .toast-region,
  .table-action,
  .text-link {
    display: none !important;
  }

  body {
    background: #fff;
  }

  .container {
    width: 100%;
  }

  .profile-banner {
    color: var(--ink);
    background: #fff;
    box-shadow: none;
    border: 1px solid var(--line);
  }

  .profile-banner__program,
  .profile-chip {
    color: var(--ink-soft);
  }

  .profile-avatar {
    color: var(--ink);
    background: var(--soft);
  }

  .panel,
  .table-wrap {
    box-shadow: none;
    break-inside: avoid;
  }

  .profile-grid {
    display: none;
  }

  .schedule-section {
    margin-top: 20px;
  }
}

