cat > /tmp/prism-test/test.cjs <<'EOF'
const { JSDOM, VirtualConsole } = require('jsdom');
const assert = require('assert');

const BASE = 'http://127.0.0.1:4173/';
const errors = [];

async function load(page) {
  const virtualConsole = new VirtualConsole();
  virtualConsole.on('jsdomError', (e) => errors.push(`${page} jsdom: ${e.message}`));
  virtualConsole.on('error', (...args) => errors.push(`${page} console: ${args.join(' ')}`));
  virtualConsole.on('warn', () => {});
  const dom = await JSDOM.fromURL(BASE + page, {
    runScripts: 'dangerously',
    resources: 'usable',
    pretendToBeVisual: true,
    virtualConsole
  });
  await new Promise((resolve) => dom.window.addEventListener('load', resolve));
  await new Promise((r) => setTimeout(r, 100));
  return dom;
}

function click(win, el) {
  assert(el, 'element to click must exist');
  el.dispatchEvent(new win.MouseEvent('click', { bubbles: true, cancelable: true }));
}

(async () => {
  {
    const dom = await load('index.html');
    const { document, localStorage } = dom.window;
    assert.strictEqual(document.querySelectorAll('#faculty-grid .faculty-card').length, 6, 'faculty cards');
    assert.strictEqual(document.querySelectorAll('#featured-grid .course-card').length, 3, 'featured cards');
    assert(document.querySelector('#featured-grid [data-course-add]'), 'featured add button');
    const add = document.querySelector('#featured-grid [data-course-add]');
    click(dom.window, add);
    assert.strictEqual(JSON.parse(localStorage.getItem('prism_plan_v1')).length, 1, 'plan count after add');
    assert.strictEqual(document.querySelector('[data-plan-count]').textContent, '1', 'nav plan badge');
    assert(document.querySelector('.toast'), 'toast shown');
    assert(document.querySelector('#featured-grid .course-state--planned'), 'card state updated');
    assert.strictEqual(document.querySelector('[data-nav="home"]').getAttribute('aria-current'), 'page', 'home active');
    console.log('PASS home interactions');
  }

  {
    const dom = await load('catalog.html?department=Design');
    const { document, window } = dom.window;
    assert.strictEqual(document.querySelectorAll('#course-grid .course-card').length, 2, 'department query filters');
    assert.strictEqual(document.querySelector('#department-filter').value, 'Design', 'department select matches query');
    const search = document.querySelector('#course-search');
    search.value = 'climate';
    search.dispatchEvent(new window.Event('input', { bubbles: true }));
    assert.strictEqual(document.querySelectorAll('#course-grid .course-card').length, 0, 'combined filter no results');
    document.querySelector('#clear-filters').click();
    assert.strictEqual(document.querySelectorAll('#course-grid .course-card').length, 15, 'clear filters restores all');
    document.querySelector('#level-filter').value = '300';
    document.querySelector('#level-filter').dispatchEvent(new window.Event('change', { bubbles: true }));
    assert.strictEqual(document.querySelectorAll('#course-grid .course-card').length, 5, 'level filter 300');
    const firstAdd = document.querySelector('#course-grid [data-course-add]');
    click(window, firstAdd);
    assert(document.querySelector('.toast'), 'catalog toast');
    assert(document.querySelector('[data-plan-count]').textContent === '1', 'catalog plan badge');
    console.log('PASS catalog interactions');
  }

  {
    const dom = await load('registration.html');
    const { document, window, localStorage } = dom.window;
    assert.strictEqual(document.querySelectorAll('#current-enrollment-body tr:not(.empty-row)').length, 2, 'seeded enrollment rows');
    assert.strictEqual(document.querySelector('#full-name').value, 'Jordan Avery', 'profile prefills name');
    assert(document.querySelector('#review-registration').disabled, 'review disabled with empty plan');
    const select = document.querySelector('#course-select');
    select.value = 'cs310';
    document.querySelector('#add-course').click();
    assert.strictEqual(document.querySelectorAll('#plan-table-body tr:not(.empty-row)').length, 1, 'plan row added');
    assert.strictEqual(document.querySelector('#plan-credits').textContent, '4', 'plan credits');
    assert.strictEqual(document.querySelector('#plan-course-count').textContent, '1', 'plan count');
    assert(!document.querySelector('#review-registration').disabled, 'review enabled');
    const planBefore = JSON.parse(localStorage.getItem('prism_plan_v1'));
    assert.deepStrictEqual(planBefore, ['cs310'], 'plan storage');
    document.querySelector('#review-registration').click();
    assert(!document.querySelector('#confirmation-modal').hidden, 'modal opens');
    assert(document.querySelector('#confirm-registration'), 'confirm button exists');
    assert(document.querySelector('#confirmation-modal').textContent.includes('CS 310'), 'modal shows course');
    document.querySelector('#confirm-registration').click();
    assert(document.querySelector('#modal-content').textContent.includes("You're all set"), 'success view');
    assert.strictEqual(JSON.parse(localStorage.getItem('prism_registered_v1')).length, 3, 'registration persisted');
    assert.deepStrictEqual(JSON.parse(localStorage.getItem('prism_plan_v1')), [], 'plan cleared');
    assert.strictEqual(document.querySelectorAll('#current-enrollment-body tr:not(.empty-row)').length, 3, 'current enrollment updated');
    assert(document.querySelector('#plan-table-body .empty-row'), 'plan empty state');
    document.querySelector('#modal-actions [data-modal-close]').click();
    console.log('PASS registration flow');
  }

  {
    const dom = await load('profile.html');
    const { document, window, localStorage } = dom.window;
    assert.strictEqual(document.querySelectorAll('#profile-course-body tr:not(.empty-row)').length, 2, 'profile enrollment rows');
    assert.strictEqual(document.querySelector('#stat-courses').textContent, '2', 'profile course stat');
    assert.strictEqual(document.querySelector('#stat-credits').textContent, '6', 'profile credit stat');
    const drop = document.querySelector('[data-drop-course]');
    click(window, drop);
    assert.strictEqual(document.querySelectorAll('#profile-course-body tr:not(.empty-row)').length, 1, 'drop updates rows');
    assert.strictEqual(document.querySelector('#stat-credits').textContent, '3', 'drop updates credits');
    assert.strictEqual(JSON.parse(localStorage.getItem('prism_registered_v1')).length, 1, 'drop persists');
    console.log('PASS profile interactions');
  }

  {
    const dom = await load('index.html');
    const { document, window } = dom.window;
    const toggle = document.querySelector('#nav-toggle');
    const nav = document.querySelector('#primary-nav');
    click(window, toggle);
    assert(nav.classList.contains('is-open'), 'mobile nav opens');
    assert.strictEqual(toggle.getAttribute('aria-expanded'), 'true', 'aria-expanded true');
    window.innerWidth = 500;
    window.dispatchEvent(new window.Event('resize'));
    click(window, toggle);
    assert(!nav.classList.contains('is-open'), 'mobile nav closes');
    console.log('PASS responsive navigation');
  }

  if (errors.length) {
    console.error('ERRORS:', errors);
    process.exitCode = 1;
  } else {
    console.log('PASS no console errors');
  }
})().catch((error) => {
  console.error(error);
  if (errors.length) console.error('Captured errors:', errors);
  process.exit(1);
});
EOF
