(async() => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
  for (const p of ['index.html','catalog.html','registration.html','profile.html']) {
    await page.goto('http://127.0.0.1:4173/'+p, { waitUntil: 'networkidle' });
    const data = await page.evaluate(() => {
      const vw = document.documentElement.clientWidth;
      const els = [...document.querySelectorAll('*')].filter(el => {
        const r=el.getBoundingClientRect(); return r.right > vw + 1 || r.left < -1 || el.scrollWidth > el.clientWidth + 1 && getComputedStyle(el).overflowX === 'visible';
      }).slice(0,20).map(el=>({tag:el.tagName, cls:el.className, id:el.id, right:Math.round(el.getBoundingClientRect().right), left:Math.round(el.getBoundingClientRect().left), sw:el.scrollWidth, cw:el.clientWidth, ox:getComputedStyle(el).overflowX}));
      return {vw, scrollWidth: document.documentElement.scrollWidth, bodyScrollWidth: document.body.scrollWidth, els};
    });
    console.log('\n'+p, JSON.stringify(data,null,2));
  }
  await browser.close();
})();
EOF
