const { chromium } = require('playwright');
const assert = require('assert');
(async() => {
  const browser = await chromium.launch();
  const errors = [];
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
  const page = await ctx.newPage();
  page.on('pageerror', e => errors.push('pageerror: '+e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('console: '+m.text()); });

  const pages = ['index.html','catalog.html','registration.html','profile.html'];
  for (const vp of [{width:390,height:844},{width:768,height:1024},{width:1024,height:900},{width:1440,height:1000}]) {
    await page.setViewportSize(vp);
    for (const p of pages) {
      await page.goto('http://127.0.0.1:4173/'+p, {waitUntil:'networkidle'});
      const overflow = await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);
      if (overflow > 0) errors.push(`${p} overflow at ${vp.width}: ${overflow}px`);
    }
  }

  await page.setViewportSize({width:1440,height:1000});
  await page.goto('http://127.0.0.1:4173/index.html',{waitUntil:'networkidle'});
  for (const href of ['catalog.html','registration.html','profile.html','index.html']) {
    const links = await page.$$eval(`a[href="${href}"]`, els => els.length);
    assert(links > 0, 'link to '+href);
  }

  await page.click('#nav-toggle');
  const navOpen = await page.$eval('#primary-nav', el => el.classList.contains('is-open'));
  assert(navOpen, 'nav opens');
  await page.setViewportSize({width:390,height:844});
  await page.click('#nav-toggle').catch(()=>{});
  await page.goto('http://127.0.0.1:4173/catalog.html', {waitUntil:'networkidle'});
  await page.fill('#course-search','climate');
  assert.strictEqual(await page.locator('#course-grid .course-card').count(), 1, 'search climate');
  await page.click('#clear-filters');
  assert.strictEqual(await page.locator('#course-grid .course-card').count(), 15, 'clear filters');
  await page.fill('#course-search','design');
  assert.strictEqual(await page.locator('#course-grid .course-card').count(), 2, 'search design');
  await page.fill('#course-search','zzzzzz');
  assert(await page.locator('#catalog-empty').isVisible(), 'empty state visible');
  await page.click('#clear-filters');
  await page.selectOption('#availability-filter','few');
  assert.strictEqual(await page.locator('#course-grid .course-card').count(), 3, 'few seats');

  await page.goto('http://127.0.0.1:4173/registration.html',{waitUntil:'networkidle'});
  await page.selectOption('#course-select','cs310');
  await page.click('#add-course');
  await page.click('#review-registration');
  assert(await page.locator('#confirmation-modal').isVisible(), 'modal visible');
  await page.click('#confirm-registration');
  assert((await page.locator('#modal-content').innerText()).includes("You're all set"), 'success modal');
  await page.click('#modal-actions [data-modal-close]');
  await page.goto('http://127.0.0.1:4173/profile.html',{waitUntil:'networkidle'});
  assert.strictEqual(await page.locator('#profile-course-body tr:not(.empty-row)').count(), 3, 'profile has new course');

  for (const p of pages) {
    await page.goto('http://127.0.0.1:4173/'+p,{waitUntil:'networkidle'});
  }

  console.log('Browser QA errors:', JSON.stringify(errors, null, 2));
  if (errors.length) process.exitCode = 1;
  else console.log('PASS browser QA');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
EOF
